export const applicability = 'Заводские значения NHX110, 2009. Вьетнамская комплектация требует сверки по маркировке узла; это не подтверждение полной взаимозаменяемости.';
const m = (page, label) => ({url:manual(page),label:`Honda Service Manual · ${label || `стр. ${page}`}`});
