export const categories = ['Все узлы','Двигатель','Электрика','Свет','Ходовая','Кузов'];
export const articles = [
 {id:'oil',title:'Моторное масло',category:'Двигатель',icon:'oil',summary:'Что заливать, как проверить уровень и заменить масло.',lead:'У двигателя и редуктора отдельные масляные полости. В моторе Lead 110 небольшой объём масла, поэтому уровень стоит проверять регулярно.',specs:[['Вязкость','SAE 10W-30'],['Стандарт','JASO MB · API SG или выше'],['При обычной замене','0,7 л'],['После разборки мотора','0,8 л'],['Сливной болт','24 Н·м · новая шайба']],steps:['Поставь байк на центральную подножку на ровной площадке. Прогрей двигатель и выключи его. Подготовь ёмкость для отработки.','Выкрути крышку-щуп. Выкрути сливной болт двигателя с уплотнительной шайбой и дождись полного слива. Не перепутай его с пробкой сетчатого фильтра или редуктора.','Установи новую уплотнительную шайбу. Вкрути болт от руки и затяни 24 Н·м динамометрическим ключом.','Через отверстие щупа залей рекомендованное масло. 0,7 л — справочный объём после слива; окончательно ориентируйся на щуп, не допускай перелива.','Для контрольного замера: двигатель на холостых 3–5 минут, затем выключить и подождать 2–3 минуты. Протри щуп и вставь его БЕЗ заворачивания. Уровень должен быть между метками.','Убедись, что O-ring крышки цел, закрой щуп и проверь отсутствие течей. Отработку сдай в пункт приёма.'],warning:applicability,sources:[m(89,'4-10 · уровень и стандарт'),m(90,'4-11 · замена')],system:'engine',related:['strainer','gear','maintenance']},
 {id:'strainer',title:'Масляная сетка',category:'Двигатель',icon:'filter',summary:'Обслуживаемая сетка вместо сменного картриджа.',lead:'В NHX110 используется сетчатый маслоочиститель. Сменный бумажный масляный картридж в этом регламенте не предусмотрен.',specs:[['Тип','Промываемая сетка'],['Крышка сетки','20 Н·м'],['Уплотнение','O-ring'],['Порядок','После слива моторного масла']],steps:['Сначала слей моторное масло по отдельной инструкции. Очисти место вокруг крышки сетки.','Отворачивай крышку осторожно: за ней находятся пружина, сетка и уплотнение. Запомни ориентацию деталей по рисунку Honda на странице 4-12.','Промой сетку подходящим очистителем, осмотри на повреждения. Проверь пружину и O-ring; повреждённые детали замени.','Смажь O-ring моторным маслом. Установи детали в заводском порядке, крышку затяни 20 Н·м.','Залей моторное масло, проверь уровень щупом и отсутствие подтеканий.'],warning:applicability,sources:[m(91,'4-12 · сетчатый фильтр'),m(16,'1-11 · моменты')],system:'engine',related:['oil']},
 {id:'air',title:'Воздушный фильтр',category:'Двигатель',icon:'filter',summary:'Где находится и почему его нельзя продувать.',lead:'Воздушный фильтр находится в корпусе слева от двигателя. Штатный элемент NHX110 — бумажный с вязкой пропиткой, удерживающей пыль.',specs:[['Тип','Viscous paper'],['Крышка корпуса','7 винтов'],['Крепление элемента','4 винта'],['Момент винтов','1,1 Н·м']],steps:['Выключи двигатель. Сними левую боковую сервисную облицовку по схеме Honda 3-4.','Выкрути семь винтов крышки воздушного фильтра. Сними крышку, затем крепёж самого элемента.','Замени элемент. Пропитанную бумагу не мой, не смазывай заново и не продувай сжатым воздухом: это ухудшает фильтрацию.','Удали пыль из корпуса, не допуская её во впуск. Проверь посадку уплотнения.','Установи элемент и крышку без перекоса. Винты затягивай равномерно, без срыва пластика. В пыльных/влажных условиях осматривай чаще.'],warning:'Артикул покупай по каталогу своей версии и форме снятого элемента. Фильтр Lead 125 не следует считать подходящим к Lead 110.',sources:[m(85,'4-6 · доступ'),m(86,'4-7 · элемент'),m(16,'моменты')],system:'engine',related:['breather','engine']},
 {id:'engine',title:'Доступ к двигателю',category:'Двигатель',icon:'engine',summary:'Сервисная крышка, подседельная ванна и мотор.',lead:'Для разных работ нужен разный доступ: небольшая сервисная крышка для отдельных операций, снятая подседельная ванна — для более широкого доступа к верхней части двигателя.',specs:[['Система','4Т · OHC · PGM-FI'],['Охлаждение','Жидкостное'],['Объём по документу','108 см³'],['Показ в 3D','Снятие ванны и боковой панели']],steps:['Поставь скутер устойчиво, выключи зажигание и дай мотору остыть. Открой сиденье и убери содержимое багажника.','Для доступа через подседельное пространство сверяй крепления ванны с Honda 3-8. Убери крепёж в отдельную ёмкость, чтобы ничего не упало на двигатель.','Перед извлечением ванны освободи все удерживающие элементы и проверь проводку/тросы. Не вырывай пластик усилием.','При снятии боковой панели освобождай защёлки в направлении, указанном Honda. Схема 3D показывает расположение, но не точную последовательность разборки.','После работы проверь прокладку проводки и тросов, верни ванну и все штатные крепления.'],warning:'Точные крепления VN могут отличаться от NHX110. Перед усилием сверяй панель и заводской рисунок. Открытие 3D условное, не инструкция по направлению отгибания пластика.',sources:[m(73,'3-8 · сиденье и ванна'),m(69,'3-4 · боковые крышки')],system:'engine',related:['oil','air','spark','valves']},
 {id:'spark',title:'Свеча зажигания',category:'Двигатель',icon:'spark',summary:'Маркировка свечи, зазор и доступ.',lead:'Свечу проверяют на холодном двигателе. Сначала очисти колодец, чтобы грязь не попала в цилиндр.',specs:[['Штатная NGK','CR7EH-9'],['Штатная DENSO','U22FER9'],['Зазор','0,80–0,90 мм'],['Момент','16 Н·м']],steps:['Открой сервисный доступ по Honda 4-8 и 3-8. Сними наконечник за корпус, не тяни за высоковольтный провод.','Очисти область вокруг свечи. Выкрути её подходящим свечным ключом.','Сверь маркировку и проверь электроды, изолятор и зазор. Изношенную свечу замени.','Вкрути свечу сначала рукой без перекоса. Затяни по сервисной спецификации 16 Н·м. Установи наконечник до надёжной посадки.'],warning:applicability,sources:[m(87,'4-8 · свеча'),m(15,'спецификация зажигания')],system:'engine',related:['engine','battery']},
 {id:'valves',title:'Клапаны',category:'Двигатель',icon:'engine',summary:'Зазоры и условия проверки по NHX110.',lead:'Проверка и регулировка требуют холодного двигателя, правильной ВМТ такта сжатия и щупов. Ошибка положения коленвала даёт неверный результат.',specs:[['Впуск','0,16 ± 0,02 мм'],['Выпуск','0,25 ± 0,02 мм'],['Контргайка регулировки','10 Н·м']],steps:['Сверь модификацию двигателя. Открой заводскую процедуру Honda 4-9 / 4-10.','На холодном двигателе сними нужные крышки и выставь ВМТ такта сжатия по заводским меткам.','Измерь щупом зазор между регулировочным винтом и стержнем клапана. При регулировке удерживай винт во время затяжки контргайки.','Обязательно повторно измерь зазор после затяжки и проворота по процедуре Honda. Проверь уплотнения при сборке.'],warning:'Это справочные параметры и маршрут к заводской процедуре, не полный гайд для первого ремонта. Не регулируй по значениям от Lead 125.',sources:[m(88,'4-9 · положение'),m(89,'4-10 · зазоры')],system:'engine',related:['engine','spark']},
 {id:'breather',title:'Сапун картера',category:'Двигатель',icon:'filter',summary:'Прозрачная дренажная трубка и конденсат.',lead:'В дренажной трубке вентиляции картера собираются влага и масляные отложения. Частые короткие поездки и дождь требуют более частого осмотра.',specs:[['Расположение','У корпуса воздушного фильтра'],['После слива','Вернуть пробку и хомут']],steps:['Найди штатную дренажную трубку вентиляции по рисунку Honda 4-7. Не отсоединяй основной шланг вентиляции.','Подставь небольшую ёмкость, сними пробку дренажа и слей накопившуюся жидкость.','Верни пробку и фиксатор. Проверь, что трубка не треснула и не пережата.'],warning:applicability,sources:[m(86,'4-7 · вентиляция картера')],system:'engine',related:['air','oil']},
 {id:'gear',title:'Масло в редукторе',category:'Двигатель',icon:'oil',summary:'Отдельная замена масла задней передачи.',lead:'По заводскому NHX110 в редукторе применяется SAE 10W-30 JASO MB. Не подставляй автоматически 80W-90 из универсальных советов для скутеров.',specs:[['Масло NHX110','10W-30 · JASO MB · API SG+'],['При сливе','0,10 л'],['После разборки','0,12 л'],['Обе пробки','13 Н·м · новые шайбы']],steps:['Поставь байк на центральную подножку. Очисти корпус редуктора возле задней оси слева.','Убедись, что заливная/контрольная пробка отворачивается. Подставь ёмкость; затем сними контрольную и сливную пробки с шайбами.','Медленно проворачивай заднее колесо рукой для слива. Установи сливную пробку с новой шайбой и затяни 13 Н·м.','Заправь рекомендованным для своей версии маслом до контрольного уровня по Honda 4-15. Справочно после слива — 0,10 л.','Установи контрольную пробку с новой шайбой, 13 Н·м. Проверь течи.'],warning:applicability,sources:[m(94,'4-15 · редуктор')],system:'drive',related:['cvt','oil']},
 {id:'cvt',title:'Вариатор и ремень',category:'Двигатель',icon:'drive',summary:'Сухой привод, износ ремня и роликов.',lead:'CVT находится за левой крышкой двигателя. Внутри работают ремень, ведущий шкив, ролики, сцепление и ведомый шкив.',specs:[['Привод','Сухой V-Matic'],['Предел ширины ремня NHX110','17,5 мм'],['Контроль','Трещины · расслоения · износ']],steps:['Сними нужную боковую облицовку и левую крышку по главе Honda 11. Перед снятием запомни положение каждого болта.','Осмотри ремень на трещины, расслоения и следы масла. Измерь ширину и сверь с пределом именно своего ремня.','Проверь ролики, рабочие поверхности шкивов и сцепление по сервисному руководству. Не наноси масло на ремень, шкивы и фрикционные накладки.','Для гаек вариатора и сцепления нужны штатные фиксаторы и точный момент из главы 11. Не блокируй шкив случайной отвёрткой.'],warning:'Точные артикулы, длину ремня и массу роликов VN нужно подтвердить по своему двигателю. Число 17,5 мм — сервисный предел NHX110, не размер нового ремня.',sources:[m(93,'4-14 · ремень'),m(246,'глава 11 · CVT')],system:'drive',related:['gear','maintenance']},
 {id:'battery',title:'Аккумулятор',category:'Электрика',icon:'battery',summary:'Как добраться, снять клеммы и выбрать замену.',lead:'В заводской схеме NHX110 аккумулятор стоит за передней центральной облицовкой. В каталоге VN указан YTX7; совместимость замены определяй по установленной батарее.',specs:[['Напряжение','12 В'],['VN каталог','YTX7 · 31500-GGE-900'],['Замена OEM в каталоге','31500-GFM-B10'],['Ёмкость NHX110','6 А·ч · не VN-подтверждение'],['Снятие клемм','Сначала −, затем +']],steps:['Выключи зажигание. В NHX110 снимай переднюю центральную облицовку: по два винта с обратной стороны и снизу; освободи бобышки и сдвинь панель вниз для выхода язычков (Honda 3-4).','Перед работой проверь фактическое расположение АКБ на VN. Сначала отсоедини минусовую клемму, затем плюсовую. Не замкни инструментом плюс на раму.','Сними держатель и вынь батарею. Запиши маркировку, размеры, полярность и тип клемм перед покупкой.','Установи батарею и держатель. Подключи сначала плюс, затем минус. Верни защитный колпачок плюса и облицовку.','Заряжай устройством для подходящего типа АКБ по инструкции производителя батареи. Герметичную MF-батарею не вскрывай и не доливай воду.'],warning:'VN-каталог и NHX110 расходятся в обозначениях батареи. 6 А·ч не заявлено как точная ёмкость твоего экземпляра. Доступ в 3D показан по NHX110 и требует сверки на байке.',sources:[m(377,'18-6 · снятие'),m(69,'3-4 · центральная панель'),{url:'https://xemay.net/san-pham/31500-gge-900/',label:'VN каталог · АКБ YTX7'}],system:'electric',related:['fuses','starter']},
 {id:'fuses',title:'Все предохранители',category:'Электрика',icon:'fuse',summary:'Номиналы, замена и электросхема.',lead:'Каталог VN подтверждает предохранители 10 и 20 А. В NHX110 предусмотрены главный 20 А и три дополнительных 10 А. Распределение цепей VN по позициям пока не подтверждено.',specs:[['Главный NHX110','20 A × 1'],['Дополнительные NHX110','10 A × 3'],['VN 10 A OEM','98200-41000'],['VN 20 A OEM','98200-42000']],table:{head:['Позиция NHX110','Номинал','Применимость'],rows:[['Главный','20 A','VN: номинал есть в каталоге'],['Дополнительный 1','10 A','Цепь сверить по крышке/схеме'],['Дополнительный 2','10 A','Цепь сверить по крышке/схеме'],['Дополнительный 3','10 A','Цепь сверить по крышке/схеме']]},steps:['Выключи зажигание. Открой доступ к электрическому оборудованию по схеме своего байка.','Сверь маркировку на крышке блока. Извлеки подозреваемый предохранитель и проверь перемычку или прозвони его мультиметром.','Поставь предохранитель того же типа и строго того же номинала. Не ставь больший номинал и не делай перемычку.','Если новый сразу перегорел, отключи цепь и найди короткое замыкание/повреждение проводки. Повторная замена без диагностики не устраняет причину.'],warning:'Назначение конкретных гнёзд VN не установлено: подписи FI / свет / зажигание нельзя переносить из другой версии. Открой полную заводскую электросхему 22-2 и сверь цвета проводов.',sources:[v(65068,'F26 · электропроводка'),m(15,'1-10 · номиналы'),m(421,'22-2 · электросхема')],system:'electric',related:['battery','starter','dashboard']},
 {id:'headlight',title:'Фара: ближний / дальний',category:'Свет',icon:'light',summary:'HS5 35/30 Вт, доступ и замена лампы.',lead:'В каталоге вьетнамского Lead 110 периода 2009–2013 указана двухнитевая HS5. Более мощная лампа может перегреть отражатель и проводку.',specs:[['Лампа VN','HS5 · 12 В'],['Дальний / ближний','35 / 30 Вт'],['OEM VN','34901-GFM-971'],['Доступ NHX110','Передняя крышка руля']],steps:['Выключи свет и зажигание. Дай лампе остыть. Для NHX110 сними зеркала и переднюю крышку руля по Honda 3-6, осторожно разъедини 4P-разъём.','Сними пыльник и отсоедини 3P-разъём лампы. Поверни лампу против часовой стрелки и вынь.','Сверь HS5 и мощность со старой лампой. Не касайся стекла пальцами. Вставь новую и зафиксируй поворотом по часовой стрелке.','Подключи разъём. Установи пыльник надписью TOP вверх, проверь его посадку и верни крышку.','Проверь ближний и дальний. Направление света отрегулируй по заводской процедуре и местным требованиям, не ослепляя встречных.'],warning:'Тип и мощность подтверждены каталогом VN. Разборка описана по NHX110: количество винтов и разъёмы сверяй с фактической облицовкой.',sources:[v(65009,'F1 · фара'),m(405,'21-4 · замена'),m(71,'3-6 · крышка руля')],system:'lights',related:['bulbs','front-turn','dashboard']},
 {id:'front-turn',title:'Передние поворотники',category:'Свет',icon:'turn',summary:'Доступ к патрону и проверка мигания.',lead:'Для NHX110 передние поворотники используют лампы 12 В 21 Вт. Точный цоколь и мощность VN нужно сверить с вынутой лампой и патроном.',specs:[['NHX110','12 В · 21 Вт × 2 спереди'],['Цоколь VN','Требует проверки'],['Патрон','Поворот против часовой']],steps:['Выключи зажигание. Найди заднюю часть патрона в передней облицовке. Если доступа нет, открывай панели по Honda 3 и 21-5.','Поверни патрон против часовой стрелки и вынь его. Для описанной в NHX110 лампы нажми на колбу и поверни против часовой.','Сравни мощность и расположение штифтов старой и новой лампы. Не меняй силой лампу с несовпадающим цоколем.','Собери и проверь оба указателя. Учащённое мигание часто требует проверки ламп и контактов. LED-замена может изменить работу реле.'],warning:applicability,sources:[m(406,'21-5 · передние поворотники'),m(15,'1-10 · лампы')],system:'lights',related:['headlight','tail','bulbs']},
 {id:'tail',title:'Задний свет и номер',category:'Свет',icon:'light',summary:'Стоп, габарит, поворотники и подсветка номера.',lead:'В заднем фонаре отдельные функции: двухнитевая лампа стопа/габарита, поворотники и лампа подсветки номера. Каждую проверяй отдельно.',specs:[['Стоп / габарит VN','12 В · 21/5 Вт'],['Поворотник VN','12 В · 21 Вт'],['Номер VN','12 В · 5 Вт']],steps:['Выключи зажигание и дай лампам остыть. По NHX110 сними заднюю нижнюю облицовку для доступа к патронам (Honda 21-6).','Стоп/поворотники: поверни патрон против часовой стрелки, вынь; нажми на лампу и поверни против часовой. Сверь цоколь и мощность.','Подсветка номера: сними винты блока, освободи крючок, вытягивай патрон и затем лампу по рисунку Honda.','Не смешивай двухконтактную 21/5 Вт с одноконтактной 21 Вт. Верни уплотнения и всю облицовку.','Проверь габарит, стоп от каждого рычага, левый/правый поворот и освещение номера.'],sources:[v(65059,'F25 · задний фонарь'),{url:'https://xemay.net/san-pham/bo-phu-tung-f-23-catalogue-chan-bun-sau-honda-lead-110-01-2009-03-2013/',label:'VN каталог · F23 · номер'},m(407,'21-6 · замена')],warning:'Мощности подтверждены каталогом VN; цоколи и порядок снятия облицовки требуют сверки. OEM собраны в таблице всех ламп.',system:'lights',related:['bulbs','fuses']},
 {id:'bulbs',title:'Таблица всех ламп',category:'Свет',icon:'light',summary:'Мощности, артикулы и границы применимости.',lead:'VN — данные каталога вьетнамской версии 2009–2013. NHX — заводской сервисный мануал 2009; такие позиции не подтверждены для твоей приборки.',table:{head:['Где','Тип / мощность','Источник / OEM'],rows:[['Фара','HS5 · 12 В · 35/30 Вт','VN · 34901-GFM-971'],['Стоп / габарит','12 В · 21/5 Вт','VN · 34906-GFM-890'],['Задние поворотники','12 В · 21 Вт','VN · 34904-GFM-B20'],['Номер','12 В · 5 Вт','VN · 34907-GFM-B20'],['Лампа приборки (роль не установлена)','T6.5 · 12 В · 3 Вт','VN · 34908-KM1-671'],['Передние поворотники','12 В · 21 Вт ×2','NHX · сверить VN'],['Подсветка приборки','12 В · 1,7 Вт ×2','NHX · сверить VN'],['Индикаторы поворота','12 В · 3 Вт ×2','NHX · сверить VN'],['Индикатор дальнего','12 В · 1,7 Вт','NHX · сверить VN'],['PGM-FI / MIL','LED','NHX · не сменная колба']]},warning:'Не все цоколи подтверждены. Не заказывай по одной только мощности. Для приборки VN назначение каждой лампы и количество нужно проверить по снятой панели.',sources:[v(65009,'F1'),v(65059,'F25'),v(65018,'F2 · приборка'),m(15,'1-10 · вся светотехника')],system:'lights',related:['headlight','tail','dashboard']},
 {id:'dashboard',title:'Приборная панель',category:'Электрика',icon:'gauge',summary:'Показания, лампы и доступ к подсветке.',lead:'Панель показывает скорость, пробег, уровень топлива и температуру охлаждающей жидкости; индикаторы сообщают о поворотах, дальнем свете и работе PGM-FI.',specs:[['Подсветка NHX110','12 В · 1,7 Вт ×2'],['Повороты NHX110','12 В · 3 Вт ×2'],['Дальний NHX110','12 В · 1,7 Вт'],['PGM-FI / MIL','Светодиод']],steps:['До старта проверь индикаторы при включении зажигания. MIL обычно загорается на несколько секунд и гаснет. Постоянный свет или мигание требует диагностики.','Если не горит подсветка, сначала проверь предохранители и разъёмы. Для доступа к лампам NHX110 снимается передняя крышка руля.','Вытяни соответствующий патрон и лампу по Honda 21-7. Перед заменой прочитай её маркировку: в каталоге VN есть T6.5 3 Вт, но назначение патрона не установлено.','Для снятия панели целиком заводская процедура требует заднюю крышку руля, разъёмы переключателей и три винта. Проверь проводку и работу после сборки.'],warning:'Не считай индикатор FI лампой давления масла или напоминанием о замене. Набор и мощность подсветки NHX110 не подтверждены для VN.',sources:[m(408,'21-7 · приборка'),v(65018,'F2 · VN'),m(127,'PGM-FI · коды')],system:'cockpit',related:['bulbs','fuses','fuel']},
 {id:'starter',title:'Запуск и зарядка',category:'Электрика',icon:'battery',summary:'Что проверить, если стартер не крутит.',lead:'Диагностика начинается с батареи, клемм и предохранителей. Не замыкай реле стартера инструментом.',specs:[['АКБ NHX110 при 20 °C','>12,8 В — заряжена'],['Нужна зарядка NHX110','<12,3 В'],['Электрика','12 В · стартер']],steps:['Проверь положение зажигания и штатные блокировки запуска, нажми тормозной рычаг. Убедись, что стоп-сигнал реагирует.','Если нет питания совсем, проверь клеммы и главный предохранитель. Если слышен щелчок, проверь заряд батареи и соединения под нагрузкой.','Если стартер крутит, а двигатель не запускается, проверь топливо, MIL и работу системы впрыска по главе Honda 6. Не крути стартер непрерывно.','Для проверки зарядки используй методику главы Honda 18. Напряжение покоя само по себе не доказывает исправность батареи под нагрузкой.'],warning:'Порог напряжения дан для заводской NHX110 батареи. Тип и характеристики установленной АКБ сверяй отдельно. Не меняй детали до диагностики.',sources:[m(15,'спецификация АКБ'),m(374,'глава 18 · зарядка'),m(394,'глава 20 · стартер')],system:'electric',related:['battery','fuses','fuel']},
 {id:'coolant',title:'Охлаждающая жидкость',category:'Двигатель',icon:'coolant',summary:'Расширительный бачок, уровень и перегрев.',lead:'Lead 110 использует жидкостное охлаждение. Уровень проверяют на холодном двигателе в расширительном бачке; радиатор и бачок — разные части системы.',specs:[['Система NHX110','0,41 л · двигатель + радиатор'],['Бачок NHX110','0,10 л'],['Рекомендация Honda','PRE-MIX COOLANT']],steps:['Полностью остуди двигатель. Поставь скутер ровно и найди расширительный бачок по Honda 4-13. Сверь уровень с LOWER/UPPER.','При необходимости долей подходящий готовый coolant до верхней отметки через бачок. Не выбирай жидкость по одному цвету и не смешивай неизвестные составы.','Если уровень падает, проверь шланги, соединения, радиатор и помпу. Для осмотра по NHX110 снимаются боковая панель, ванна и крышка радиатора.','При перегреве остановись и выключи двигатель. Не откручивай горячую крышку радиатора.','Полная замена требует слива, правильного заполнения и удаления воздуха по главе 7. Объём бачка не равен заправочному объёму всей системы.'],warning:applicability,sources:[m(11,'1-6 · объёмы'),m(92,'4-13 · уровень'),m(93,'4-14 · осмотр'),m(183,'7-8 · полная замена')],system:'engine',related:['engine','maintenance']},
 {id:'brakes',title:'Передний тормоз',category:'Ходовая',icon:'brake',summary:'Диск, колодки и тормозная жидкость.',lead:'Спереди установлен гидравлический дисковый тормоз. Проверяй отсутствие течей, остаток накладок и уверенный ход рычага.',specs:[['Тип','Гидравлический диск'],['Жидкость NHX110','DOT 3 или DOT 4'],['Контроль','Уровень · течи · износ']],steps:['Поставь скутер ровно, выровняй бачок на руле. Проверь уровень и отсутствие течей по Honda 4-16.','Осмотри канавки-индикаторы износа колодок. Если дошли до предела — замени комплект по заводской процедуре.','Если уровень низкий, сначала проверь износ колодок и герметичность. Не доливай автоматически до максимума поверх изношенных колодок.','Для вскрытия гидролинии, замены жидкости и прокачки используй Honda главу 16. Защити краску: тормозная жидкость её повреждает.','После работ до поездки восстанови нормальный ход рычага и проверь торможение на безопасной малой скорости.'],warning:'Потеря давления, течь или рычаг до рукоятки — причина не ехать до устранения. Тип жидкости сверь с крышкой бачка своей VN версии.',sources:[m(95,'4-16 · жидкость и износ'),m(96,'4-17 · тормозная система'),m(326,'глава 16 · гидравлика')],system:'wheels',related:['rear-brake','tyres']},
 {id:'rear-brake',title:'Задний тормоз и CBS',category:'Ходовая',icon:'brake',summary:'Барабан, тросы и комбинированная система.',lead:'Сзади — механический барабанный тормоз. Свободный ход, состояние тросов и настройка комбинированной системы проверяются по заводской процедуре.',specs:[['Задний тормоз','Механический барабан'],['Проверка накладок','Стрелка относительно метки'],['Настройка CBS','По своему сервисному мануалу']],steps:['Проверь плавный ход рычагов, возврат тросов и отсутствие повреждений оболочек.','Нажми тормоз и сравни стрелку на тормозном рычаге барабана с предельной меткой. Достижение предела требует осмотра/замены колодок.','Регулировку свободного хода и уравнителя выполняй в порядке Honda 4-17 и далее; универсальное число оборотов гайки не подходит.','После регулировки проверь, что заднее колесо свободно вращается при отпущенном тормозе и стоп-сигнал включается при нажатии.'],warning:'Не перетягивай трос ради короткого хода рычага: тормоз может постоянно подтормаживать. Числовые настройки VN здесь не подтверждены.',sources:[m(95,'контроль износа'),m(96,'тормоза и регулировка'),m(99,'выключатель стопа')],system:'wheels',related:['brakes','tail']},
 {id:'tyres',title:'Шины и колёса',category:'Ходовая',icon:'wheel',summary:'Размеры, холодное давление и состояние резины.',lead:'Перед поездкой проверь давление на холодных шинах, трещины, повреждения, износ протектора и состояние вентилей. Для давления приоритет у наклейки твоего скутера.',specs:[['Передняя NHX110','90/90-12 44J'],['Задняя NHX110','100/90-10 56J'],['Давление','Сверь наклейку VN'],['Контроль','На холодных шинах']],steps:['Измерь давление до поездки. Сравни его с наклейкой для нагрузки: один водитель или водитель с пассажиром.','Осмотри протектор, боковины и вентили. Найди индикаторы износа и проверь, нет ли гвоздей, вздутий и глубоких трещин.','Сверь размер, индексы нагрузки/скорости и направление вращения при замене. Год выпуска резины оцени вместе с её состоянием.','После удара или при биении проверь колесо, подшипники и подвеску в мастерской.'],warning:'Размеры NHX110 приведены как ориентир. Давление и размеры для твоего VN экземпляра подтвердить по наклейке и установленным шинам.',sources:[m(14,'размеры/давления'),m(101,'4-22 · колёса и шины')],system:'wheels',related:['brakes','suspension']},
 {id:'suspension',title:'Подвеска и рулевое',category:'Ходовая',icon:'suspension',summary:'Вилка, амортизатор и люфты.',lead:'Вилка спереди и блок двигатель-маятник сзади должны двигаться плавно, без утечек, стуков и заеданий.',specs:[['Спереди','Телескопическая вилка'],['Сзади','Unit swing'],['Проверка','Течи · люфт · крепления']],steps:['Осмотри перья вилки и задний амортизатор на течи и повреждения. Проверь крепления визуально.','С зажатым передним тормозом мягко прожми вилку. Ход должен быть плавным, без металлических стуков.','Проверь рулевое на плавность поворота и люфт по Honda 4-24. Не подтягивай рулевые подшипники наугад.','При течи, погнутых деталях или люфтах проведи ремонт до поездки. Разборку вилки и замену жидкости делай по главе своей версии.'],warning:applicability,sources:[m(100,'4-21 · подвеска'),m(103,'4-24 · рулевые подшипники')],system:'wheels',related:['tyres','brakes']},
 {id:'seat',title:'Сиденье и багажник',category:'Кузов',icon:'seat',summary:'Открыть, закрыть и получить доступ под ванну.',lead:'Под сиденьем — большая формованная багажная ванна. Открытое сиденье и снятая ванна дают разный доступ: мотор закрыт самой ванной.',specs:[['Открытие','Штатным замком сиденья'],['Багажная ванна','Отдельно снимаемая деталь'],['В 3D','Сиденье на переднем шарнире']],steps:['Поставь байк устойчиво, выключи двигатель. Открой сиденье штатным замком без усилия и удерживай до устойчивого открытого положения.','Убери вещи. Для обслуживания двигателя недостаточно поднять сиденье — при необходимости снимается сама ванна по Honda 3-8.','Перед закрытием проверь, что ключи не остались внутри, проводка и вещи не мешают замку. Опусти и защёлкни сиденье.','Потяни сиденье вверх, чтобы убедиться в фиксации. При заедании осмотри замок и трос; не захлопывай силой.'],warning:'В 3D шарнир и объём показаны условно. Грузоподъёмность багажника VN не подтверждена: сверяй наклейку внутри, не подменяй её объёмом в литрах.',sources:[m(73,'3-8 · сиденье и ванна')],system:'body',related:['engine','glove','panels']},
 {id:'glove',title:'Передний бардачок',category:'Кузов',icon:'box',summary:'Передний отсек и внутренний щиток.',lead:'Передний отсек предназначен для небольших вещей. Его крышка не является универсальным доступом к аккумулятору: в NHX110 АКБ открывают через другую панель.',specs:[['Расположение','Внутренний передний щиток'],['В 3D','Откидная крышка'],['Нагрузка VN','Сверить наклейку']],steps:['Открой крышку штатной защёлкой/замком твоей комплектации без усилия.','Проверь петлю, защёлку и отсутствие попавших в механизм предметов. Не перегружай крышку.','Если снимаешь внутренний щиток для ремонта, сверяй порядок панелей Honda 3-12. Освободи весь крепёж, прежде чем тянуть.','Закрой крышку и проверь фиксацию перед поездкой. Не оставляй ценные вещи в отсеке без присмотра.'],warning:'Устройство замка и отсека VN нужно подтвердить на самом байке. 3D показывает принцип открывания, не точную заводскую конструкцию.',sources:[m(77,'3-12 · передний внутренний щиток')],system:'body',related:['battery','panels']},
 {id:'panels',title:'Облицовка и крепления',category:'Кузов',icon:'box',summary:'Порядок снятия пластика без сломанных защёлок.',lead:'У облицовок есть винты, бобышки и направленные язычки. Панель не должна отрываться силой, даже если видимые винты уже сняты.',specs:[['Передняя центральная','Honda 3-4'],['Крышка руля','Honda 3-6'],['Багажная ванна','Honda 3-8']],steps:['Открой карту панелей Honda 3-2. Определи, какие детали перекрывают нужную панель.','Разложи крепёж по панелям: винты могут иметь разную длину. Снимай на остывшем байке, не сгибай старый хрупкий пластик.','Передняя центральная NHX110: два винта сзади, два снизу, освобождение бобышек и движение вниз для язычков.','При обратной сборке сначала правильно заведи язычки и проверь зазоры, затем наживи винты. Не стягивай перекошенные детали винтами.'],warning:'Последовательность и крепёж VN сверяй с реальными панелями. Шесть перемещаемых деталей 3D — учебное упрощение.',sources:[m(67,'3-2 · карта панелей'),m(69,'3-4'),m(71,'3-6'),m(73,'3-8')],system:'body',related:['seat','engine','battery']},
 {id:'fuel',title:'Топливо и PGM-FI',category:'Двигатель',icon:'fuel',summary:'Бак, впрыск и индикатор неисправности.',lead:'PGM-FI управляет подачей топлива электронно. Ошибка впрыска не определяется одним симптомом: нужны питание, коды и проверки по заводской схеме.',specs:[['Подача','Электронный впрыск PGM-FI'],['Топливо','Неэтилированный бензин по наклейке VN'],['MIL','Зафиксировать свет/мигания']],steps:['Заправляй с выключенным двигателем. Используй топливо, соответствующее наклейке/руководству своей версии. Не заливай выше штатного уровня.','Если MIL остаётся гореть или мигает, запиши поведение и условия появления, затем используй индекс Honda 6-18 и диагностическую процедуру.','Не замыкай неизвестные контакты диагностического разъёма и не стирай коды до чтения. Снятие клеммы не является надёжным стиранием DTC.','Топливная система под давлением. До снятия шлангов выполняется заводская процедура сброса давления; замену насоса и форсунки делай по главе 6.'],warning:'Бензин, допустимый этанол и объём бака для VN здесь не подтверждены. Не переноси данные Lead 125 или японского JF19 автоматически.',sources:[m(110,'глава 6 · PGM-FI'),m(127,'индекс MIL'),m(141,'проверка топливной линии')],system:'engine',related:['dashboard','starter','spark']},
 {id:'controls',title:'Руль и переключатели',category:'Электрика',icon:'gauge',summary:'Свет, сигнал, газ, рычаги и зеркала.',lead:'Перед стартом проверь возврат ручки газа, работу поворотников, сигнала, дальнего света и обоих тормозных рычагов.',specs:[['Газ','Свободный возврат во всех положениях руля'],['Стоп-сигнал','Проверять от обоих рычагов'],['Зеркала','Обзор без изменения посадки']],steps:['На выключенном двигателе поверни руль в обе стороны и проверь, что газ сам возвращается и трос не натянут.','Включи зажигание и проверь левый/правый поворот, сигнал и доступные режимы освещения.','Проверь стоп-сигнал при нажатии каждого рычага. Отрегулируй зеркала до начала движения.','Если переключатель не работает, проверь разъём и питание по Honda главе 21. Не заливай блок неподходящим очистителем.'],warning:'Органы управления и блокировки VN могут отличаться. Не предполагай наличие Smart Key, Idling Stop, USB или масляного напоминания на модели 2009.',sources:[m(84,'4-5 · ручка газа'),m(99,'4-20 · стоп-сигнал'),m(402,'глава 21 · выключатели')],system:'cockpit',related:['headlight','dashboard','rear-brake']},
 {id:'maintenance',title:'Регламент обслуживания',category:'Двигатель',icon:'tool',summary:'Заводская таблица ТО и ежедневные проверки.',lead:'Полный заводской регламент — таблица Honda 4-4. Интервалы зависят от рынка, условий и времени; регламент Lead 125 нельзя использовать для Lead 110.',specs:[['Основная таблица','Honda Service Manual · стр. 83'],['До поездки','Шины · тормоза · свет · жидкости'],['Пыль / вода / нагрузка','Проверки чаще']],steps:['Проверь применимость регламента по модели двигателя и рынку. Если история неизвестна, начни с диагностики и базового обслуживания, а не с обнуления пробега.','Веди записи: дата, пробег, операция, материал и артикул. Учитывай и километры, и срок.','В заводской таблице проверь масло, сетку, воздушный фильтр, свечу, клапаны, ремень, редуктор, охлаждение, тормоза, тросы, колёса, подшипники и крепления.','При пыльной, мокрой эксплуатации и частых коротких поездках выполняй дополнительные проверки, указанные Honda.'],warning:'Точная таблица периодичности Honda Vietnam 2009 пока не найдена. До её подтверждения сайт не выдаёт предполагаемые интервалы за регламент твоего байка. Полный ремонтный мануал доступен по ссылке.',sources:[m(83,'4-4 · график ТО'),m(80,'глава 4 · обслуживание')],system:'engine',related:['oil','air','cvt','coolant']}
];
